WITH cleaned AS (SELECT *, LENGTH(segment) segment_length FROM customers WHERE city IS NOT NULL AND city IS NOT DISTINCT FROM 'New York'), scored AS (SELECT *, MAX(age) OVER w_grp last7_max_age, SUM(age) OVER w_grp last7_sum_age, AVG(age) OVER w_grp last7_avg_age FROM cleaned WINDOW w_grp AS (PARTITION BY segment, city ORDER BY age, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), with_windows AS (SELECT *, ROUND(last7_avg_age / SUM(last7_avg_age) OVER (PARTITION BY country, segment), 4) last7_avg_age_share, SUM(last7_avg_age) OVER (PARTITION BY segment ORDER BY segment_length, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_last7_avg_age FROM scored), not_flagged AS (SELECT s.* FROM with_windows s WHERE EXISTS (SELECT 1 FROM subscriptions c WHERE c.customer_id = s.id AND c.start_date >= s.signup_date)), with_last AS (SELECT s.*, x.account_status, x.account_account_type FROM not_flagged s JOIN LATERAL (SELECT c.status AS account_status, c.account_type AS account_account_type FROM accounts c WHERE c.customer_id = s.id ORDER BY c.opened_date DESC, c.id DESC LIMIT 1) x ON TRUE) SELECT id, name, email, country, city, segment, signup_date, credit_limit, segment_length FROM with_last ORDER BY segment;
